using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.LowLevel;using Bokumyaku.Presentation;using Bokumyaku.Diagnostics;
public static class PhaseTimingCheck {
static BokumyakuGame g;static PlayerLoopSystem original;static double start;static int frame;static string snapshot;
public static object Run(){g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(g==null||!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated Play required");BattleTiming.Reset();BattleTiming.Enabled=true;for(int i=0;i<BattleTiming.Capacity+1;i++){using(BattleTiming.Measure("capacity",0)){} }if(BattleTiming.Capture().Length!=BattleTiming.Capacity||BattleTiming.DroppedSamples!=1)throw new Exception("Overflow accounting failed");BattleTiming.Enabled=false;using(BattleTiming.Measure("disabled",0)){}if(BattleTiming.DroppedSamples!=1)throw new Exception("Disabled recording");BattleTiming.Reset();BattleTiming.Enabled=true;original=PlayerLoop.GetCurrentPlayerLoop();PlayerLoopTiming.Install();PlayerLoopTiming.Install();g.AbandonRun();g.TryStartRun(42);g.SetPaused(true);snapshot=JsonUtility.ToJson(g.Run.CaptureState());start=EditorApplication.timeSinceStartup;frame=Time.frameCount;Application.runInBackground=true;EditorApplication.update+=Poll;return "Phase timing and bounded-log verification started";}
static void Poll(){if(g!=null&&EditorApplication.isPlaying&&Time.frameCount-frame<60&&EditorApplication.timeSinceStartup-start<15){EditorApplication.QueuePlayerLoopUpdate();return;}EditorApplication.update-=Poll;PlayerLoopTiming.Restore();PlayerLoopTiming.Restore();BattleTiming.Enabled=false;var current=PlayerLoop.GetCurrentPlayerLoop();bool restored=Same(original,current);var samples=BattleTiming.Capture();bool phase=samples.Any(s=>s.section.StartsWith("Loop."));File.WriteAllText(Path.GetFullPath("../docs/evidence/phase-timing-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{passed=restored&&phase&&g!=null&&snapshot==JsonUtility.ToJson(g.Run.CaptureState()),restored,phase,capacity=BattleTiming.Capacity,overflowCheck=true,disabledCheck=true,dropped=BattleTiming.DroppedSamples,frames=Time.frameCount-frame,samples,method="Isolated Editor Play; bounded overflow/disabled assertions, duplicate installation/restoration, live top-level PlayerLoop phase timing; exact loop hierarchy/delegates restored."},Newtonsoft.Json.Formatting.Indented));}
static bool Same(PlayerLoopSystem a,PlayerLoopSystem b){if(a.type!=b.type||a.updateDelegate!=b.updateDelegate||a.updateFunction!=b.updateFunction||a.loopConditionFunction!=b.loopConditionFunction)return false;if(a.subSystemList==null||b.subSystemList==null)return a.subSystemList==b.subSystemList;if(a.subSystemList.Length!=b.subSystemList.Length)return false;for(int i=0;i<a.subSystemList.Length;i++)if(!Same(a.subSystemList[i],b.subSystemList[i]))return false;return true;}
}
